contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) external returns (bool reverted) {
        vm.prank(caller);
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) { reverted = false; } catch { reverted = true; }
