            (caller == address(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001) && !reverted) ||
            (caller != address(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001) && reverted)
        );
    }
}

