        bool reverted;
        (bool success, ) = address(c).call(abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            uint64(0), uint64(0), uint256(0), bytes32(0), uint64(0), bytes32(0), uint256(0), uint256(0)
        ));
        reverted = !success;

        assert(reverted);
    }
