pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        // caller must not be the depositor account and must not be address(0)
        vm.assume(caller != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        vm.assume(caller != address(0));
        vm.assume(caller.code.length == 0); // EOA to ensure no unexpected fallback logic
        vm.prank(caller);
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            // If the call succeeds, the contract must have allowed a non-depositor, non-zero address -> buggy behavior
            assertTrue(false);
        } catch {
            // Expected: the reference contract reverts; buggy version would succeed
            assertTrue(true);
        }
    }
}

